package com.spaceagent.platform.runtime;
import com.fasterxml.jackson.databind.ObjectMapper;import com.spaceagent.platform.runtime.domain.*;import com.spaceagent.platform.runtime.infrastructure.persistence.PostgresRuntimeGraphSessionRepository;import org.flywaydb.core.Flyway;import org.flywaydb.core.api.MigrationVersion;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import java.time.*;import static org.assertj.core.api.Assertions.*;
@Testcontainers(disabledWithoutDocker=true) class RuntimeGraphSessionRepositoryTest {static final Instant NOW=Instant.parse("2026-09-08T00:00:00Z");static final String HASH="sha256:"+"a".repeat(64);@Container static final PostgreSQLContainer<?> PG=new PostgreSQLContainer<>("pgvector/pgvector:pg17").withDatabaseName("graph_session").withUsername("spaceagent").withPassword("spaceagent");static DriverManagerDataSource ds;@BeforeAll static void migrate(){ds=new DriverManagerDataSource(PG.getJdbcUrl(),PG.getUsername(),PG.getPassword());Flyway.configure().dataSource(ds).locations("classpath:db/platform-server","classpath:db/platform-runtime").load().migrate();}@Test void persistsCasCommandIdempotencyAndCleanupAcrossRestart(){var repo=new PostgresRuntimeGraphSessionRepository(new JdbcTemplate(ds),new ObjectMapper());var s=RuntimeGraphSession.start(java.util.UUID.randomUUID().toString(),"tenant","owner","run",HASH,NOW);repo.insert(s);var waiting=s.propose("cmd-1",HASH,NOW.plusSeconds(1));assertThat(repo.update(waiting,s.revision(),s.state())).isTrue();assertThat(repo.update(waiting,s.revision(),s.state())).isFalse();var command=new RuntimeGraphCommand(s.id(),"cmd-1",HASH,RuntimeGraphCommand.State.PENDING,1,NOW,NOW);assertThat(repo.insertCommandIfAbsent(command)).isEqualTo(command);assertThat(repo.insertCommandIfAbsent(command)).isEqualTo(command);assertThatThrownBy(()->repo.insertCommandIfAbsent(new RuntimeGraphCommand(s.id(),"cmd-1","sha256:"+"b".repeat(64),RuntimeGraphCommand.State.PENDING,1,NOW,NOW))).isInstanceOf(IllegalStateException.class);var complete=waiting.confirm("cmd-1",HASH,NOW.plusSeconds(2)).complete(NOW.plusSeconds(3));assertThat(repo.update(complete,waiting.revision(),waiting.state())).isTrue();var restarted=new PostgresRuntimeGraphSessionRepository(new JdbcTemplate(ds),new ObjectMapper());assertThat(restarted.findByRunId("tenant","owner","run")).contains(complete);assertThat(restarted.cleanupCompletedBefore(NOW.plusSeconds(4))).isEqualTo(1);assertThat(restarted.findById("tenant","owner",s.id())).isEmpty();}@Test void v1058UpgradesIdempotently(){String schema="graph_upgrade";var scoped=com.spaceagent.platform.support.PostgresSchemaDataSource.forSchema(PG,schema);Flyway.configure().dataSource(scoped).locations("classpath:db/platform-server","classpath:db/platform-runtime").target(MigrationVersion.fromVersion("1057")).load().migrate();var jdbc=new JdbcTemplate(scoped);assertThat(jdbc.queryForObject("SELECT to_regclass('platform_runtime_graph_sessions') IS NULL",Boolean.class)).isTrue();var flyway=Flyway.configure().dataSource(scoped).locations("classpath:db/platform-server","classpath:db/platform-runtime").load();flyway.migrate();flyway.migrate();assertThat(jdbc.queryForObject("SELECT to_regclass('platform_runtime_graph_commands') IS NOT NULL",Boolean.class)).isTrue();assertThat(jdbc.queryForObject("SELECT version FROM flyway_schema_history WHERE success ORDER BY installed_rank DESC LIMIT 1",String.class)).isEqualTo("1098");}}
